import React, { useState } from 'react';
import axios from 'axios';
import './Prediction.css';

function Prediction() {
  const questions = [
    { key: 'age', question: "Hi! Let's predict your diabetes risk. How old are you?", type: 'number', min: 0, max: 120 },
    { key: 'gender', question: "What is your gender? (Female, Male, Other)", type: 'text', options: ['Female', 'Male', 'Other'] },
    { key: 'bmi', question: "What's your BMI (Body Mass Index)?", type: 'number', min: 10, max: 50 },
    { key: 'hbA1c_level', question: "What's your HbA1c Level (%)?", type: 'number', min: 3, max: 15 },
    { key: 'blood_glucose_level', question: "What's your Blood Glucose Level (mg/dL)?", type: 'number', min: 50, max: 300 },
    { key: 'hypertension', question: "Do you have hypertension? (yes/no)", type: 'boolean' },
    { key: 'heart_disease', question: "Do you have heart disease? (yes/no)", type: 'boolean' },
    { key: 'smoking_history', question: "What is your smoking history? (never, former, current, not current, ever)", type: 'text', options: ['never', 'former', 'current', 'not current', 'ever'] },
  ];

  const [currentStep, setCurrentStep] = useState(0);
  const [answers, setAnswers] = useState({});
  const [inputValue, setInputValue] = useState('');
  const [prediction, setPrediction] = useState(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');

  const currentQuestion = questions[currentStep];

  const validateInput = (value) => {
    if (currentQuestion.type === 'number') {
      const num = Number(value);
      if (isNaN(num)) return false;
      if (num < currentQuestion.min || num > currentQuestion.max) return false;
    }
    if (currentQuestion.type === 'boolean') {
      if (!['yes', 'no'].includes(value.toLowerCase())) return false;
    }
    if (currentQuestion.options) {
      if (!currentQuestion.options.includes(value)) return false;
    }
    return true;
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!validateInput(inputValue.trim())) {
      setError('Invalid input. Please enter a valid answer.');
      return;
    }

    setError('');
    // Normalize inputs
    let val = inputValue.trim();
    if (currentQuestion.type === 'number') val = Number(val);
    if (currentQuestion.type === 'boolean') val = val.toLowerCase() === 'yes' ? 1 : 0;

    setAnswers(prev => ({
      ...prev,
      [currentQuestion.key]: val,
    }));

    setInputValue('');

    if (currentStep + 1 < questions.length) {
      setCurrentStep(currentStep + 1);
    } else {
      // All questions answered, call prediction API
      setIsLoading(true);
      try {
        const response = await axios.post('http://localhost:8000/predict', {
          ...answers,
          [currentQuestion.key]: val, // include last answer
        }, {
          headers: { 'Content-Type': 'application/json' },
        });
        setPrediction(response.data);
      } catch (err) {
        setError('Prediction failed. Please try again.');
      } finally {
        setIsLoading(false);
      }
    }
  };

  return (
    <div className="prediction-container">
      <h2>Diabetes Risk Prediction Chatbot</h2>

      {!prediction && (
        <form onSubmit={handleSubmit}>
          <label>{currentQuestion.question}</label>
          {currentQuestion.type === 'text' && currentQuestion.options ? (
            <select
              value={inputValue}
              onChange={e => setInputValue(e.target.value)}
              required
            >
              <option value="">-- Select --</option>
              {currentQuestion.options.map(opt => (
                <option key={opt} value={opt}>{opt}</option>
              ))}
            </select>
          ) : (
            <input
              type={currentQuestion.type === 'number' ? 'number' : 'text'}
              value={inputValue}
              onChange={e => setInputValue(e.target.value)}
              min={currentQuestion.min}
              max={currentQuestion.max}
              required
              autoFocus
            />
          )}
          <button type="submit" disabled={isLoading}>
            {isLoading ? 'Processing...' : 'Next'}
          </button>
          {error && <p className="error-message">{error}</p>}
        </form>
      )}

      {prediction && (
        <div className={`prediction-result ${prediction.prediction ? 'high-risk' : 'low-risk'}`}>
          <h3>Prediction Result</h3>
          <p><strong>Risk Level:</strong> {prediction.interpretation}</p>
          <p><strong>Probability:</strong> {(prediction.probability * 100).toFixed(1)}%</p>
          <p className="recommendation">
            {prediction.prediction
              ? "We recommend consulting with a healthcare professional for further evaluation."
              : "Maintain healthy habits to keep your risk low."}
          </p>
          <button onClick={() => {
            setPrediction(null);
            setAnswers({});
            setCurrentStep(0);
          }}>Start Over</button>
        </div>
      )}
    </div>
  );
}

export default Prediction;
